/**
 * Page-level list of form errors after a failed submit (`design/components/error-summary.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/error-summary.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  chooseListItem,
  derived,
  elementRef,
  listItems,
  mountEffect,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/error-summary.module.css'

export interface ErrorSummaryError {
  label: string
  fieldId: string
}

/** Page-level list of form errors after a failed submit: the inputs it takes, by the React member's prop names. */
export interface ErrorSummaryProps {
  /**
   * Errors in form order, the navigation order (Stat's rule); an empty list renders nothing.
   */
  errors: ErrorSummaryError[]
  /**
   * Text from the app ("The ticket can't be raised yet"); the vocabulary writes no error copy.
   */
  title: string
}

/** Page-level list of form errors after a failed submit. */
@Component({
  selector: 'pm-error-summary',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Icon],
  // prettier-ignore
  template: `@if (e1()) {<div
[attr.class]="e2()"
role="alert"
data-member="error-summary"
[pmRef]="root"
><!-- glyph -->
<span
[attr.class]="e3()"
><pm-icon
name="error"
size="md"
></pm-icon></span>
<!-- body -->
<div
[attr.class]="e4()"
><!-- title -->
<p
[attr.class]="e5()"
>{{ e6() }}</p>
<!-- list -->
<ul
[attr.class]="e7()"
[pmRef]="list"
>@for (error of e8(); track e9(error, $index); let at = $index) {<li><!-- entry -->
<a
[attr.class]="e10()"
[attr.href]="e11(error)"
(click)="h1($event, error)"
>{{ e12(error) }}</a></li>}</ul></div></div>}`,
})
export class ErrorSummary {
  /**
   * Errors in form order, the navigation order (Stat's rule); an empty list renders nothing.
   */
  readonly errors = input.required<ErrorSummaryProps['errors']>()
  /**
   * Text from the app ("The ticket can't be raised yet"); the vocabulary writes no error copy.
   */
  readonly title = input.required<ErrorSummaryProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: { errors: () => this.errors(), title: () => this.title() },
  })
  protected readonly $p = this.$.props
  protected readonly list = elementRef<HTMLElement>()
  protected readonly root = elementRef<HTMLElement>()
  protected readonly follow = derived(() => (event: MouseEvent, fieldId: string) => {
    const control = document.getElementById(fieldId)
    if (control === null) return
    event.preventDefault()
    control.focus()
    control.scrollIntoView({ block: 'nearest' })
  })
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return this.$p.errors.length > 0
  }

  protected e2() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return styles.root
  }

  protected e3() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return styles.glyph
  }

  protected e4() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return styles.body
  }

  protected e5() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return styles.title
  }

  protected e6() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return this.$p.title
  }

  protected e7() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return styles.list
  }

  e8() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return this.$p.errors
  }

  protected e9(error: Each<ReturnType<ErrorSummary['e8']>>, at: number) {
    return `${at}-${error.fieldId}`
  }

  protected e10() {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return styles.link
  }

  protected e11(error: Each<ReturnType<ErrorSummary['e8']>>) {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return `#${error.fieldId}`
  }

  protected h1($event: MouseEvent, error: Each<ReturnType<ErrorSummary['e8']>>): void {
    if (!(this.$p.errors.length > 0)) return
    this.follow.value($event, error.fieldId)
  }

  protected e12(error: Each<ReturnType<ErrorSummary['e8']>>) {
    if (!(this.$p.errors.length > 0)) return undefined as never
    return error.label
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'ErrorSummary',
      element: () => this.root.value,
      state: () => ({ items: listItems(this.list.value, styles.link) }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => chooseListItem(this.list.value, styles.link, value),
        },
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
